Function word <- HowItWent(codigo As Integer)
  Define word As String;
  If codigo = 200 Then
    word <- "fine";
  Else
    word <- "problem";
  EndIf
EndFunction

Algorithm Estado
  Define codigo As Integer;
  Read codigo;
  Write HowItWent(codigo);
EndAlgorithm

